  str_extra_mission_task_desc_4500001 = "ที่ไหนสักแห่งในเขตชานเมืองของลูโมโพลิส หน่วยจู่โจมของเรดีเซล เวรนช์ กำลังออกปล้นสะดม ดูเหมือนจะได้ข้าวของมากมาย",
  str_extra_mission_task_desc_4500002 = "เห็นได้ชัดว่ากลุ่มทหารธรรมดาไร้ฝีมือไม่สามารถต่อกรกับบร็อคได้ การกระทำของเขาเป็นการดูถูกเหยียดหยามกันชัด ๆ",
  str_extra_mission_task_desc_4500003 = "ด้วยการขัดขวางของสองหน่วยผู้พิทักษ์และคาร์ลีน ในที่สุดบร็อคก็ \"พ่ายแพ้\" และถูกส่งไปที่คุกลูโมโพลิส",
  str_extra_mission_task_desc_4500004 = "เพื่อนที่ไม่คาดคิด โจนา ได้หลบหนีออกจากคุกพร้อมกับบร็อค เธอดูบ้าระห่ำหน่อย ๆ หวังว่าจะไม่ทำอะไรแผลง ๆ นะ",
  str_extra_mission_task_desc_4500005 = "มีแต่โจนาเท่านั้นที่คิดหนีด้วยการกระโดดออกจากลูโมโพลิส ในการหลบหนีที่บ้าดีเดือดเช่นนี้ หน่วยผู้พิทักษ์ได้แต่มองดูพวกเขาจากไป",
  str_extra_mission_task_desc_4500006 = "บร็อคกลับมารวมตัวกับทีมอีกครั้ง พวกเขาได้พบกับเรจินา ซึ่งมาเป็นกำลังเสริมร่วมกัน อย่างไรก็ตาม มีการเผชิญหน้าอิคลิพไซท์เกิดขึ้นใกล้ ๆ และดูเหมือนทุกคนจะพร้อมลุยแล้ว",
  str_extra_mission_task_desc_4500007 = "เมืองใต้ดินของอิลลูมินาถูกอิคลิพไซท์บุกรุก แต่ทำไมถึงมุ่งไปที่หางของชาโรนาเท่านั้นล่ะ?!",
  str_extra_mission_task_desc_4500008 = "เป็นอีกครั้งที่แขกไม่ได้รับเชิญหาเรื่องชวนโมโหมาให้ชาโรนา และครั้งนี้ดูเหมือนจะมีบางอย่างที่สำคัญถูกขโมยไป",
  str_extra_mission_task_desc_4500009 = "ทั้งคู่ต้องเริ่มตามหาเบาะแสศัตรู และต้องรู้ให้ได้ว่ามันขโมยอะไรไป การเดินทางครั้งนี้ต้องไม่ราบรื่นอย่างแน่นอน ",
  str_extra_mission_task_desc_4500010 = "ชาโรนาต้องปกป้องฟิลิชีที่กำลังหลับ ทั้งยังต้องจัดการอิคลิพไซท์ที่เข้ามาโจมตีไปด้วย นี่มันไม่ง่ายเอาซะเลย ",
  str_extra_mission_task_desc_4500011 = "ฟิลิชีที่ตื่นขึ้นมาดูจะมีท่าทางแปลกๆ? และใครคือ \"ยูมิ\"? ชาโรนารู้สึกไม่แน่ใจกับสิ่งที่เธอเห็น ",
  str_extra_mission_task_desc_4500012 = "ฟิลิชีที่กำราบอีกตัวตนของเธอไว้ได้ชั่วคราวในที่สุดก็จำได้แล้วว่าโบว์ลิงเกอร์มีสิ่งที่พวกเขากำลังตามหา! ",
  str_extra_mission_task_desc_4500013 = "บ่ายวันหนึ่งในฤดูร้อน ขณะที่คอนนอลลีและแอนตันเพื่อนของเธอกำลังทำความสะอาดห้องใต้ดินของร้านกาแฟ พวกเขาก็ได้ยินเสียงประหลาดร้องขอความช่วยเหลือ",
  str_extra_mission_task_desc_4500014 = "ผู้ที่สร้างความวุ่นวายให้กิลด์จะต้องถูกลงโทษอย่างหนัก! โรบินและเดย์นายอมรับภารกิจ มุ่งมั่นที่จะจับตัวคนร้ายให้ได้",
  str_extra_mission_task_desc_4500015 = "ในการค้นหาแมวหุ่นยนต์ คอนนอลลีกับแอนตันได้มาถึงท่าจอดยาน และที่ยืนอยู่ตรงหน้าพวกเขาก็คือ ทหารคุ้มกันลูโม",
  str_extra_mission_task_desc_4500016 = "เหยื่อรายใหม่คือเจ้าของแมวหุ่นยนต์! เขาต้องดื่ม\nสารละลายเข้าไปแน่ๆ เราต้องช่วยเขา!",
  str_extra_mission_task_desc_4500017 = "อิคลิพไซท์ซ่อนตัวอยู่ในเงามืด พวกมันกัดกินแขนและขาของเหยื่อที่หมดสติ",
  str_extra_mission_task_desc_4500018 = "ขายสินค้าต้องห้ามและโจมตีสมาชิกกิลด์! ต้องหาให้ได้ว่าใครอยู่เบื้องหลังเรื่องพวกนี้!",
  str_extra_mission_task_desc_4500019 = "พวกที่กล้ารุกรานนอร์ธแลนด์จะต้องถูกฝังอยู่ใต้หิมะอันหนาวเหน็บอย่างไร้ร่องรอย",
  str_extra_mission_task_desc_4500020 = "คาร์ลีนมาที่นอร์ธแลนด์เพียงลำพังตั้งแต่อายุยังน้อย แทนที่จะเป็นความมหัศจรรย์อันแสนโรแมนติก กลับเป็นลมหนาวเย็นยะเยือกแห่งอาร์กติกที่ต้อนรับการมาถึงของเธอ",
  str_extra_mission_task_desc_4500021 = "ความล้มเหลวครั้งแล้วครั้งเล่า ถึงแม้จะเป็นแค่เงาของอิคลิพไซท์ที่ถูกควบคุมด้วยเวทมนตร์ แต่มันช่างร้ายกาจอย่างไม่น่าเชื่อ",
  str_extra_mission_task_desc_4500022 = "ในฝันร้าย เบธเลเฮมฝันถึงอดีตของเธอตอนที่นอร์ธแลนด์เกือบจะล่มสลายจากการรุกรานของอิคลิพไซท์มากมายนับไม่ถ้วน",
  str_extra_mission_task_desc_4500023 = "การฝึกฝนอย่างไม่ลดละเริ่มได้ผล การเข้าใจและใช้ประโยชน์จากจุดอ่อนของศัตรู คือหนทางสู่ชัยชนะ!",
  str_extra_mission_task_desc_4500024 = "ใช้หอกในมือของคุณทำลายสิ่งกีดขวางสุดท้าย! แสงออโรราอันงดงามจะกลายเป็นสะพานที่เชื่อมต่อวิญญาณทั้งสองดวง!",
  str_extra_mission_task_desc_4500001_long = "ที่ไหนสักแห่งในเขตชานเมืองของลูโมโพลิส หน่วยจู่โจมของเรดีเซล เวรนช์ กำลังออกปล้นสะดม\nดูเหมือนจะได้ข้าวของมากมาย\nแม้ว่าพวกเขาจะพบกับหน่วยลาดตระเวนของลูโมโพลิส แต่กัปตันบร็อคก็ไม่ตื่นตระหนก\nอันที่จริงดูเหมือนว่าเขาอยากต่อสู้เต็มที",
  str_extra_mission_task_desc_4500002_long = "เห็นได้ชัดว่ากลุ่มทหารธรรมดาไร้ฝีมือไม่สามารถต่อกรกับบร็อคได้\nการกระทำของเขาเป็นการดูถูกเหยียดหยามกันชัด ๆ!\nแต่ด้วยการขัดขวางของสองหน่วยผู้พิทักษ์และคาร์ลีน ในที่สุดบร็อคก็พ่ายแพ้",
  str_extra_mission_task_desc_4500003_long = "บร็อคถูกส่งไปที่คุกลูโมโพลิส\nและที่นี่เองเขาได้พบกับเพื่อนที่ไม่คาดคิด โจนา\nคนที่ไม่แยแสกับทุกสิ่ง\nเธอทำลายที่คุมขังแล้วก็หลบหนีไปพร้อมกับบร็อค!",
  str_extra_mission_task_desc_4500004_long = "โจนาดูบ้าระห่ำหน่อย ๆ หวังว่าจะไม่ทำอะไรแผลง ๆ นะ\nและแล้วเธอก็กระโดดออกจากลูโมโพลิสไปพร้อมกับบร็อค\nมันคือการหลบหนีที่แลกด้วยชีวิต",
  str_extra_mission_task_desc_4500005_long = "ในการหลบหนีที่บ้าดีเดือดเช่นนี้ หน่วยผู้พิทักษ์ได้แต่มองดูพวกเขาจากไป\nบร็อคกลับมารวมตัวกับทีมอีกครั้ง พวกเขาได้พบกับเรจินา ซึ่งมาเป็นกำลังเสริมร่วมกัน\nอย่างไรก็ตาม มีการเผชิญหน้าอิคลิพไซท์เกิดขึ้นใกล้ ๆ และดูเหมือนทุกคนจะพร้อมลุยแล้ว",
  str_extra_mission_task_desc_4500006_long = "หน่วยผู้พิทักษ์ก็ถูกดึงเข้ามาร่วมการต่อสู้ด้วยโดยบังเอิญ ทั้งสองฝ่ายตกลงที่จะละทิ้งความแตกต่างเพื่อหันมาจัดการกับศัตรูคนเดียวกัน\nหลังจากการสู้รบ\nเมื่อได้มีโอกาสเผชิญหน้ากับซินซาซึ่งผู้นำของเรดีเซล เวรนช์ คาร์ลีนกลับลังเลที่จะลงมือ\nจึงได้แต่มองพวกบ้าระห่ำจากไป",
  str_extra_mission_task_desc_4500007_long = "ในเมืองใต้ดินของอิลลูมินา ชาโรนาถูกปลุกให้ตื่นโดยผู้มาเยือนแปลกหน้า\nที่ดูเหมือนว่าจะมาเพื่อเล่นกับหางของเธอ\nเมืองใต้ดินถูกศัตรูบุกรุกงั้นหรือ?\nนี่มันเรื่องอะไรกันแน่?",
  str_extra_mission_task_desc_4500008_long = "แขกผู้มาเยือนที่น่าฉงนกลับมาอีกครั้ง ชาโรนาตามมันไป แต่ทั้งหมดนี้เป็นแค่การเบี่ยงเบนความสนใจของเธอหรือเปล่านะ?\nหลังจากเอาชนะพวกสมุนได้แล้ว ชาโรนาก็กลับมาที่ห้องข่าวกรอง และเห็นฟิลิชีกำลังหลับอยู่\nนอกจากชาโรนาจะต้องมาอยู่กับฟิลิชีที่สูญเสียสติสัมปชัญญะ ตอนนี้ชาโรนาต้องร่วมมือกับเธอด้วยเหรอเนี่ย?!",
  str_extra_mission_task_desc_4500009_long = "ดีนะที่โชคเข้าข้าง ฟิลิชีพบเส้นทางลับจนได้\nฟิลิชีที่คอยระวังหลังให้ชาโรนาได้เปลี่ยนความคิดที่ชาโรนามีต่อเธอ",
  str_extra_mission_task_desc_4500010_long = "พอถึงช่วงหน้าสิ่วหน้าขวานทีไร อาการผล็อยหลับของฟิลิชีก็กำเริบทุกทีสิน่า!\nศัตรูเห็นจังหวะเหมาะก็ไม่ปล่อยให้โอกาสนี้หลุดมือ\nชาโรนาเริ่มปกป้องเพื่อนตัวน้อย เธอเริ่มใจอ่อนให้กับ...",
  str_extra_mission_task_desc_4500011_long = "หลังจากตื่นขึ้นมา ฟิลิชีก็เป็นเหมือนคนละคนอย่างสิ้นเชิง ทั้งโหดเหี้ยมและทำตัวแปลก ๆ\nชาโรนารู้ได้ทันทีว่าฟิลิชีเป็น \"อิคลิพไซท์\" ที่คอยรังควานเธอนี่เอง!\nหรือว่าที่เป็นแบบนี้เพราะฟิลิชีเป็นคนหลายบุคลิก?\nถ้าอยากปลุกฟิลิชีให้ตื่น ชาโรนาต้องใช้หางของเธอเพื่อ \"แหย่เจ้าแมว\" ",
  str_extra_mission_task_desc_4500012_long = "ในที่สุดฟิลิชีกับชาโรนาก็เดินทางมาถึงจุดสิ้นสุดของเส้นทางลับ ตั้งใจที่จะช่วงชิงของล้ำค่าที่ถูกขโมยไปกลับคืนมา ซึ่งก็คือ...ปลากระป๋อง?!\nเนื่องจากอิทธิพลของยูมิ ทำให้แผนการของศัตรูล้มเหลวตั้งแต่เริ่ม\nชาโรนาและฟิลิชีได้สร้างมิตรภาพที่เหลือเชื่อจากประสบการณ์ที่น่าขันครั้งนี้\nและอิคลิพไซท์ระดับสูงที่ปรากฏตัวในอิลลูมินาคือ...?",
  str_extra_mission_task_desc_4500013_long = "บ่ายวันหนึ่งในฤดูร้อน ขณะที่คอนนอลลีและแอนตันเพื่อนของเธอกำลังทำความสะอาดห้องใต้ดินของร้านกาแฟ\nคอนนอลลีนึกถึงอดีตหลังจากเจอโน้ตดนตรีของเพลง \"บ้าน\" ในห้องใต้ดิน\nเสียงร้องขอความช่วยเหลือที่ได้ยินนั้น เป็นเสียงของ\nแมวหุ่นยนต์",
  str_extra_mission_task_desc_4500014_long = "ชายปริศนาที่ขายน้ำยาลึกลับและทำลายความสงบของกิลด์ได้หลบหนีไป!\nหลังจากภารกิจล้มเหลว เดย์นากับโรบินก็ไปที่ฮอลิเดย์คาเฟ่เพื่อพักผ่อน\nเดย์นาซ่อมแมวหุ่นยนต์ของคอนนอลลีด้วยกำลังที่รุนแรง\nแต่ก่อนที่เธอจะได้เล่นสนุกกับเพื่อนขนปุย พวกเขาก็ได้รับภารกิจใหม่\nแล้วเจ้าแมวก็หายไปอย่างลึกลับเช่นกัน",
  str_extra_mission_task_desc_4500015_long = "คอนนอลลีและแอนตันตามเบาะแสของแมวหุ่นยนต์จนมาถึงที่ท่าจอดยาน\nที่นี่พวกเขาได้พบกับเจ้าของแมวหุ่นยนต์\nผู้ชายที่ปรารถนาจะเข้าไปในลูโมโพลิส ไม่ว่าจะต้องแลกด้วยอะไรก็ตาม",
  str_extra_mission_task_desc_4500016_long = "คำพูดของเชโอลทำให้คอนนอลลีครุ่นคิดอยู่ลึก ๆ ในอดีตเธอเคยหมกมุ่นอยู่แต่ในโลกของตัวเอง\nไม่คิดว่าทุกคนในอัมบราตันก็เป็นครอบครัวของเธอ\nเครื่องสื่อสารของเดย์นามีข้อความเข้ามา \"พบเหยื่อรายใหม่\"!\nคอนนอลลีตั้งใจจะขอความช่วยเหลือจากทุกคน จึงเขียนข้อความถึงครอบครัวของเธอบนกระดานดำ",
  str_extra_mission_task_desc_4500017_long = "แม้ว่าเจ้าของแมวจะดื่มสารละลายไปแล้ว แต่เขาก็ยังคงตายและกลายเป็นเหยื่อของอิคลิพไซท์\nอาการประสาทหลอนทำให้เขาเห็นประตูเมืองลูโมโพลิสเปิดกว้างต่อหน้า\nแต่ความโหยหาในจิตใจของเขายังคงว่างเปล่า\nลูโมโพลิสไม่เคยเป็นบ้านสำหรับพวกเขาเลย",
  str_extra_mission_task_desc_4500018_long = "อิคลิพไซท์ที่ขายสินค้าต้องห้ามได้พบกับจุดจบที่สมควรได้รับ\nอย่างไรก็ตาม บ้านของช่างเครื่องกลกับแมวได้พังพินาศไปแล้ว และเขาได้ฝากแมวไว้ให้คอนนอลลีดูแล\nลูโมโพลิสที่เป็นดั่งสรวงสวรรค์ไม่ได้ช่วยคอนนอลลีเลย แต่เป็นทุกคนที่อยู่รอบตัวเธอต่างหากล่ะ!\n\"ขอบใจนะ! กลับไปที่คาเฟ่และดื่มคาปูชิโน่กันเถอะ!\"",
  str_extra_mission_task_desc_4500019_long = "นอร์ธแลนด์ดินแดนแห่งหิมะที่ไม่มีวันละลาย\nพลังทำลายล้างของน้ำแข็งและหิมะทำให้ราชินีแห่งแดนเหนือไร้ผู้ต่อกร\nแต่พลังเดียวกันนี้ก็ทำให้เธอกลายเป็นนักโทษในที่แห่งนี้เช่นเดียวกัน\nด้วยเกล็ดหิมะที่ตกลงมาอย่างไม่คาดคิด\nคนนอกกำลังเดินทางมาที่นี่",
  str_extra_mission_task_desc_4500020_long = "\"อย่าทำเรื่องไม่เหมาะสม\"\nพ่อเตรียมส่งคาร์ลีนไปที่นอร์ธแลนด์เพียงลำพัง\nราชินีดูห่างไกล ห่างเหิน เยือกเย็นราวกับน้ำแข็ง\nในฐานะคนนอกจากต่างแดน คาร์ลีนรู้สึกโดดเดี่ยวและหนาวสะท้านถึงกระดูก",
  str_extra_mission_task_desc_4500021_long = "มันอาจเป็นคำทำนายก็ได้\nเบธเลเฮมจ้องมองไปยังแสงออโรราที่กำลังเจิดจ้าอยู่เลือน ๆ ส่องประกายท่ามกลางความมืดมิดของรัตติกาล\nในพายุที่โหมกระหน่ำ เด็กน้อยคาร์ลีนพยายามโจมตีใส่เงาของอิคลิพไซท์ครั้งแล้วครั้งเล่า\nแต่ยิ่งพยายามก็ยิ่งล้มเหลวไม่เป็นท่า",
  str_extra_mission_task_desc_4500022_long = "ฝันร้ายที่หายไปนานกลับมาอีกครั้ง เบธเลเฮมมองเห็นภาพหลอนของตัวเอง\nยิ่งไปกว่านั้น เธอเห็นคาร์ลีน\n\"พลังมาพร้อมกับความโดดเดี่ยว\" แต่ทว่าเบธเลเฮมก็เต็มใจยอมรับพลังแห่งน้ำแข็งและหิมะ\nแล้วคาร์ลีนล่ะ? เมื่อถึงทางแยกเดียวกัน เธอจะเลือกเดินไปทางไหน?",
  str_extra_mission_task_desc_4500023_long = "ถ้าอยากแข็งแกร่งก็ต้องใช้ความพยายามให้มาก\nในทำนองเดียวกัน เกล็ดหิมะที่งดงามก็ต้องการความเย็นสุดขั้ว\nคาร์ลีนทำได้สำเร็จ\nใบหน้าของเธอเผยให้เห็นรอยยิ้มที่พึงพอใจ เบธเลเฮมขอให้คาร์ลีนเตรียมตัวสำหรับ \"บททดสอบที่แท้จริง\"",
  str_extra_mission_task_desc_4500024_long = "นั่นเป็นครั้งแรกที่คาร์ลีนเอาชนะอิคลิพไซท์ได้ด้วยตัวเอง\nหลังจากความตึงเครียด เบธเลเฮมก็ลูบหัวของเด็กน้อยเบา ๆ\nเธอชี้ไปยังแสงออโรราที่งดงาม\nเพื่อปกป้องออโรรา เธอจึงตัดสินใจเลือกพลังและความโดดเดี่ยว\nคาร์ลีนบอกความรู้สึก ซึ่งเป็นเหตุผลที่เธอเลือกเดินเส้นทางเดียวกันเพื่อปกป้องลูโมโพลิส",
  str_extra_mission_dec_0001 = "ในวันธรรมดาอีกวันหนึ่งที่มาพร้อมการโจรกรรมธรรมดาอีกครั้งสำหรับบร็อค สมาชิกเรดีเซล เวรนช์ ผู้มีไหวพริบ เมื่อถูกล้อมรอบด้วยเทวทูตผู้พิทักษ์ของคาร์ลีน เป็นเรื่องธรรมดาที่เขาจะถูกลูโมโพลิสจับตัวไป อย่างไรก็ตาม คนที่รอเขาอยู่หลังห้องขังอันหนาวเหน็บนั้นคือใบหน้าที่คุ้นเคย...โจนาแห่งเรดีเซล เวรนช์...",
  str_extra_mission_dec_0002 = "ในช่วงเวลาดึกดื่น ณ เมืองแกนน่อน ชาโรนากำลังนอนหลับสบายเช่นเดียวกับคนอื่น ๆ ของอิลลูมินา จนกระทั่ง \"ใครบางคน\" มาจับหางของเธอ ความวุ่นวายแสนแปลกประหลาดเป็นแบบนี้อยู่หลายวัน ในที่สุดเมื่อชาโรนาสุดที่จะทนก็สามารถจับผู้กระทำความผิดได้ แต่เธอกลับได้เพื่อนร่วมทีมชวนปวดหัวเพิ่มมาอีกหนึ่งคน ฟิลิชี...",
  str_extra_mission_dec_0003 = "ในบรรยากาศช่วงบ่ายที่ชวนขี้เกียจ และท่วงทำนองของเพลง \"บ้าน\" จากกระดาษโน้ตดนตรีที่เก่าจนเหลืองดังขึ้น จากท้องถนนของอัมบราตัน เด็กสาวขี้อายคอนนอลลีมองขึ้นไปที่ลูโมโพลิส ช่างเป็นวังที่งดงาม สวรรค์สำหรับผู้ศรัทธา และเป็นที่พำนัก แต่ไม่ใช่บ้าน โดยเฉพาะสำหรับผู้เดินทางเพียงลำพัง...",
  str_extra_mission_dec_0004 = "นอร์ธแลนด์ถูกปกคลุมไปด้วยน้ำแข็งและหิมะ แยกออกจากโลกภายนอกมาหลายชั่วอายุคน ประตูวังของราชินีถูกปิดเอาไว้อย่างแน่นหนา เช่นเดียวกับหัวใจที่เยือกเย็นของเธอ อย่างไรก็ตาม ประตูที่หนักอึ้งกลับถูกเปิดออกอย่างไม่คาดคิดโดยเกล็ดหิมะที่อ่อนนุ่ม ซึ่งมีขนาดเล็กแต่มั่นคง และแหงนมองออโรราเป็นอาจิณ"
}
return config
